Here is a complete, idiomatically structured Terraform implementation for the specified scenario. It uses a modular approach with environment-aware conditional logic, strict security controls, and separation of dev/prod configurations.

## Directory Structure
```text
.
├── main.tf
├── variables.tf
├── outputs.tf
├── environments
│   ├── dev.tfvars
│   └── prod.tfvars
└── README.md
```

## 1. `variables.tf`
Defines inputs for environment differentiation and required infrastructure references.

```hcl
variable "environment" {
  description = "Deployment environment (dev or prod)"
  type        = string
  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_id" {
  description = "VPC ID where RDS will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs for RDS placement"
  type        = list(string)
}

# Security-sensitive values (must be provided via SOPS/secrets manager, never committed)
variable "db_password" {
  description = "PostgreSQL master password"
  type        = string
  sensitive   = true
}

variable "replication_destination_region" {
  description = "Destination region for cross-region replication (prod only)"
  type        = string
  default     = "us-west-2"
}

variable "eks_oidc_issuer_url" {
  description = "OIDC issuer URL from EKS cluster (used in prod IAM trust)"
  type        = string
  default     = ""
}
```

## 2. `main.tf`
Contains the resource definitions with conditional logic for environment-specific requirements.

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# -----------------------------------------------------------------------------
# S3 Bucket: Application Assets
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "app_assets" {
  bucket_prefix = "${var.environment}-app-assets-"
  force_destroy = false

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Encryption (AES-256 for dev, KMS for prod)
resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = var.environment == "prod" ? "aws:kms" : "AES256"
    }
    bucket_key_enabled = var.environment == "prod" ? true : false
  }
}

# Public Access Block
resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-Region Replication (Prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count = var.environment == "prod" ? 1 : 0

  bucket = aws_s3_bucket.app_assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-to-${var.replication_destination_region}"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replication_destination[0].arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replication[0].arn
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }
}

# Replication Destination Resources (Prod only)
resource "aws_s3_bucket" "replication_destination" {
  count = var.environment == "prod" ? 1 : 0

  bucket = "${var.environment}-app-assets-replica-${var.replication_destination_region}"
  region = var.replication_destination_region

  tags = { Environment = var.environment }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = var.environment == "prod" ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replication_destination" {
  count = var.environment == "prod" ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replication_destination" {
  count = var.environment == "prod" ? 1 : 0
  bucket = aws_s3_bucket.replication_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "replication" {
  count = var.environment == "prod" ? 1 : 0
  description = "KMS key for S3 replication encryption"
  deletion_window_in_days = 7
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL Instance
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "app" {
  name       = "${var.environment}-rds-subnet-group"
  subnet_ids = var.subnet_ids

  tags = { Environment = var.environment }
}

resource "aws_db_instance" "app" {
  identifier           = "${var.environment}-app-db"
  engine               = "postgres"
  engine_version       = "14.9"
  instance_class       = var.environment == "prod" ? "db.t3.medium" : "db.t3.micro"

  allocated_storage    = 20
  max_allocated_storage = var.environment == "prod" ? 100 : 20
  storage_type         = "gp3"

  db_name              = "appdb"
  username             = "postgres"
  password             = var.db_password
  skip_final_snapshot  = true

  multi_az             = var.environment == "prod" ? true : false
  storage_encrypted    = var.environment == "prod" ? true : false
  kms_key_id           = var.environment == "prod" ? aws_kms_key.db.key_id : null

  db_subnet_group_name = aws_db_subnet_group.app.name

  vpc_security_group_ids = [aws_security_group.rds.id]

  backup_retention_period = var.environment == "prod" ? 14 : 7
  deletion_protection     = true
  publicly_accessible     = false

  performance_insights_enabled = var.environment == "prod" ? true : false
  performance_insights_retention_period = 7

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_security_group" "rds" {
  name_prefix = "${var.environment}-rds-sg"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # Restrict to VPC internal range
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Environment = var.environment }
}

resource "aws_kms_key" "db" {
  count = var.environment == "prod" ? 1 : 0
  description = "KMS key for RDS encryption"
  deletion_window_in_days = 7
}

# -----------------------------------------------------------------------------
# IAM Role: Service Account
# -----------------------------------------------------------------------------
resource "aws_iam_role" "service_account" {
  name = "${var.environment}-app-service-account"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
      # Prod: OIDC Trust for EKS Workloads
      {
        Effect = "Allow"
        Principal = {
          Federated = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/${replace(var.eks_oidc_issuer_url, "https://", "")}"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(var.eks_oidc_issuer_url, "https://", "")}:sub" = "system:serviceaccount:app:app-service-account"
          }
        }
      }
    ]
  })

  tags = { Environment = var.environment }
}

# Least-Privilege Policy
resource "aws_iam_role_policy" "service_account" {
  name = "app-service-account-policy"
  role = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.app_assets.arn,
          "${aws_s3_bucket.app_assets.arn}/*"
        ]
      },
      # Prod: Explicitly restrict RDS actions to read-only for service account
      {
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:ListTagsForResource"
        ]
        Resource = "arn:aws:rds:${var.region}:${data.aws_caller_identity.current.account_id}:db:${var.environment}-app-db"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.region
          }
        }
      }
    ]
  })
}

# Replication IAM Role (Prod only)
resource "aws_iam_role" "replication" {
  count = var.environment == "prod" ? 1 : 0
  name = "${var.environment}-s3-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  count = var.environment == "prod" ? 1 : 0
  name = "s3-replication-policy"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.app_assets.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.app_assets.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = aws_s3_bucket.replication_destination[0].arn
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.replication[0].arn
      }
    ]
  })
}

data "aws_caller_identity" "current" {}
```

## 3. `outputs.tf`
Exports critical connection details and identifiers.

```hcl
output "s3_bucket_name" {
  description = "Name of the application S3 bucket"
  value       = aws_s3_bucket.app_assets.bucket
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = aws_db_instance.app.endpoint
  sensitive   = true
}

output "iam_role_arn" {
  description = "ARN of the service account IAM role"
  value       = aws_iam_role.service_account.arn
}

output "replication_destination_bucket" {
  description = "ARN of the replication destination bucket (prod only)"
  value       = var.environment == "prod" ? aws_s3_bucket.replication_destination[0].arn : null
}
```

## 4. Environment Configuration

### `environments/dev.tfvars`
```hcl
environment = "dev"
region      = "us-east-1"
vpc_id      = "vpc-dev-01"
subnet_ids  = ["subnet-dev-01a", "subnet-dev-01b"]

# Secret management: In practice, this is injected via SOPS or external secrets
# db_password = "${sops_decrypt("vault://secrets/dev/app/db_password")}"
```

### `environments/prod.tfvars`
```hcl
environment = "prod"
region      = "us-east-1"
vpc_id      = "vpc-prod-01"
subnet_ids  = ["subnet-prod-01a", "subnet-prod-01b", "subnet-prod-01c"]

replication_destination_region = "us-west-2"
eks_oidc_issuer_url = "https://oidc.eks.us-east-1.amazonaws.com/id/PRODCLUSTER123"

# Secret management: SOPS encrypted value or external provider injection
# db_password = "${sops_decrypt("vault://secrets/prod/app/db_password")}"
```

## Usage Instructions

### Initialize and Deploy Dev
```bash
terraform init
terraform plan -var-file=environments/dev.tfvars -out=dev.tfplan
terraform apply dev.tfplan
```

### Initialize and Deploy Prod
```bash
terraform init
terraform plan -var-file=environments/prod.tfvars -out=prod.tfplan
terraform apply prod.tfplan
```

### Workspace Alternative
If using workspaces instead of tfvars:
```bash
terraform workspace new dev
terraform apply -var-file=environments/dev.tfvars

terraform workspace new prod
terraform apply -var-file=environments/prod.tfvars
```

## Key Compliance Points

1. **Bucket Security**: Versioning enabled, encryption enforced (AES-256 dev/KMS prod), public access fully blocked.
2. **RDS Hardening**: Deletion protection on, backup retention 7+ days, multi-AZ and encryption in prod, no public access.
3. **Secrets**: `db_password` is marked `sensitive`; integration with SOPS/external secrets is indicated via comments.
4. **IAM Least Privilege**: No wildcard actions in prod; explicit resource ARNs used; OIDC trust for EKS workloads.
5. **Environment Isolation**: Separate tfvars ensure independent state and configuration; prod replication destination is isolated.
